const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function airbnbHotelSummary(property){
 const listings=airbnbListings.filter(l=>l.property===property);
 if(!listings.length)return observations.find(o=>o.property===property&&o.platform==='Airbnb');
 const rated=listings.filter(l=>Number.isFinite(l.score)&&Number.isFinite(l.reviewCount)&&l.reviewCount>0);
 const count=rated.reduce((sum,l)=>sum+l.reviewCount,0);
 return {property,platform:'Airbnb',computed:true,url:'#airbnbMap',score:count?rated.reduce((sum,l)=>sum+l.score*l.reviewCount,0)/count:null,count,label:count?'Beregnet gennemsnit':'Ingen omtaler',note:count?`Omtrentligt gennemsnit vægtet efter antal anmeldelser på ${rated.length} værelsestyper. Beregnet fra Airbnbs afrundede opslagstal; ikke en officiel samlet Airbnb-bedømmelse.`:'Ingen af hotellets opslag har anmeldelser endnu.',roomTypes:rated.length};
}
function renderGoals(){
 const targets=reviewGoals.targets.filter(g=>(selected==='all'||selected===g.property)&&(platform==='all'||platform===g.platform));
 const num=n=>n.toLocaleString('da-DK',{minimumFractionDigits:1,maximumFractionDigits:1});
 document.querySelector('#goalRows').innerHTML=targets.map(g=>{const current=observations.find(o=>o.property===g.property&&o.platform===g.platform&&o.checked);const gap=current?Math.max(0,g.target-current.score):null;return `<tr><td><span class="property">${properties.find(p=>p.id===g.property).name}</span></td><td>${g.platform} <small>/ ${g.scale}</small></td><td>${current?num(current.score):'—'}</td><td><strong>${g.property==='jylkat'?'Mindst ':''}${num(g.target)}</strong></td><td>${gap===null?'Afventer måling':gap===0?'Målet er nået · fasthold niveauet':num(gap)+' point til målet'}</td></tr>`}).join('');
 document.querySelector('#goalsEmpty').hidden=targets.length>0;
 document.querySelector('#goalsTable').hidden=targets.length===0;
}
function render(){
 renderGoals();
 document.querySelector('#airbnbMap').hidden=(platform!=='all'&&platform!=='Airbnb')||selected==='jylkat'||selected==='summer';
 document.querySelector('#airbnbRows').innerHTML=airbnbListings.filter(l=>selected==='all'||l.property===selected).map(l=>`<tr><td>${properties.find(p=>p.id===l.property).name}</td><td><a href="${l.url}" target="_blank" rel="noopener noreferrer">${escapeHTML(l.title)}</a></td><td>${l.score?l.score.toLocaleString('da-DK')+' / 5':l.reviewCount===0?'Ingen omtaler':'Ikke registreret'}</td><td>${l.reviewCount??'—'}</td></tr>`).join('');
 document.querySelector('#places').innerHTML=[{id:'all',name:'Alle steder'},...properties].map(p=>`<button type="button" data-place="${p.id}" aria-pressed="${selected===p.id}">${p.name}</button>`).join('');
 document.querySelector('#placeTitle').textContent=selected==='all'?'Alle steder':properties.find(p=>p.id===selected).name;
 document.querySelector('#scores').innerHTML=properties.filter(p=>selected==='all'||p.id===selected).map(p=>`<tr><td><span class="property">${p.name}</span><span class="address">${p.address}</span></td>${platforms.map(pl=>{const d=pl==='Airbnb'?airbnbHotelSummary(p.id):observations.find(d=>d.property===p.id&&d.platform===pl);if(platform!=='all'&&platform!==pl)return '<td><span class="count">Ikke valgt</span></td>';if(d&&!d.url)return `<td><span class="count">${escapeHTML(d.label)}</span></td>`;if(!d)return '<td><span class="missing">—</span><span class="count">Mangler data</span></td>';return `<td><a class="score-link" href="${d.url}" target="${d.computed?'_self':'_blank'}" rel="noopener noreferrer" title="${escapeHTML(d.note)}">${d.score?`<span class="score">${d.computed?'≈ ':''}${d.score.toLocaleString('da-DK',{minimumFractionDigits:pl==='Airbnb'?2:1,maximumFractionDigits:pl==='Airbnb'?2:1})}</span><span class="count">${d.count} anmeldelser</span><span class="pending">${d.computed?'Beregnet · '+d.roomTypes+' værelsestyper':'Kontrolleret '+new Date(d.observedAt).toLocaleDateString('da-DK',{day:'numeric',month:'short',timeZone:'Europe/Copenhagen'})}</span>`:`<span class="pending">${d.label|| (d.ambiguous?'Afklar profil':'Se profil')}</span>`}</a></td>`}).join('')}</tr>`).join('');
 if(typeof renderNightReport==='function')renderNightReport();if(typeof renderReviewTopics==='function')renderReviewTopics();if(typeof renderTeamCelebration==='function')renderTeamCelebration();
}
document.querySelector('#places').addEventListener('click',e=>{const b=e.target.closest('button[data-place]');if(b){selected=b.dataset.place;render();document.querySelector(`[data-place="${selected}"]`).focus();}});
document.querySelector('#platform').addEventListener('change',e=>{platform=e.target.value;render()});render();

